<?php require_once '/var/www/html/wp-load.php'; $ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft','pending','private'],'posts_per_page'=>-1,'fields'=>'ids']); foreach($ids as $id){$p=wc_get_product($id);if(!$p)continue;$u=get_post_meta($id,'_bhc_source_url',true);$s=get_post_meta($id,'_bhc_catalog_quality_state',true);if(!$u||$s!=='reference_verified'){$t=wp_get_post_terms($id,'pa_brand',['fields'=>'names']);echo $id.'|'.$p->get_sku().'|'.($t[0]??'')."\n";}}
